def compose(f, g):
    def h(x):
        return f(g(x))
    return h

def make_multiplier(factor):
    def multiplier(x):
        return x * factor
    return multiplier

def calculate(op_name, a, b):
    ops = {
        'add': lambda x, y: x + y,
        'sub': lambda x, y: x - y,
        'mul': lambda x, y: x * y,
        'div': lambda x, y: x / y,
    }
    if op_name not in ops:
        return None
    return ops[op_name](a, b)

